      margin: closeMargin,
      pnl: netPnl,
      roePct,
      fee: Number(((pos.entryFee || 0) * frac + exitFee).toFixed(2)),
      reason,
      source: pos.source || "MANUAL",
      botId: pos.botId || null,
      botName: pos.botName || null,
      openedAt: pos.openedAt,
      closedAt: Date.now(),
      note: "",
